namespace sv_d63a46f418a84262831b602d12a190f4.Services;

public record TaskItem(int Id, string Title, string Assignee, string Priority, DateTime DueDate, string Status);

public interface ITaskService
{
    Task<List<TaskItem>> GetAllTasksAsync();
    Task<TaskItem> CreateTaskAsync(string title, string assignee, string priority, DateTime dueDate);
    Task UpdateTaskStatusAsync(int taskId, string newStatus);
}

@page "/board"
@rendermode InteractiveServer
@using sv_d63a46f418a84262831b602d12a190f4.Services
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2 class="mb-3">Project Board</h2>

@if (_loading)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasksAsync">Retry</button>
    </div>
}
else
{
    <!-- Stats Bar -->
    <div class="row g-2 mb-3">
        <div class="col"><div class="card text-center p-2"><strong>@_allTasks.Count</strong><br /><small class="text-muted">Total</small></div></div>
        <div class="col"><div class="card text-center p-2"><strong>@GetColumnTasks("To Do").Count</strong><br /><small class="text-muted">To Do</small></div></div>
        <div class="col"><div class="card text-center p-2"><strong>@GetColumnTasks("In Progress").Count</strong><br /><small class="text-muted">In Progress</small></div></div>
        <div class="col"><div class="card text-center p-2"><strong>@GetColumnTasks("Done").Count</strong><br /><small class="text-muted">Done</small></div></div>
        <div class="col"><div class="card text-center p-2 @(OverdueCount > 0 ? "border-danger" : "")"><strong class="@(OverdueCount > 0 ? "text-danger" : "")">@OverdueCount</strong><br /><small class="text-muted">Overdue</small></div></div>
    </div>

    <!-- Search -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..." @bind="_searchText" @bind:event="oninput" />
    </div>

    <!-- Columns -->
    <div class="row g-3">
        @foreach (var column in _columns)
        {
            var tasks = GetFilteredColumnTasks(column);
            var colIndex = Array.IndexOf(_columns, column);
            <div class="col-md-4">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@column</strong>
                        <span class="badge bg-secondary">@tasks.Count</span>
                    </div>
                    <div class="card-body d-flex flex-column gap-2" style="min-height:200px;overflow-y:auto;">
                        @foreach (var task in tasks)
                        {
                            <div class="card shadow-sm">
                                <div class="card-body p-2">
                                    <h6 class="card-title mb-1">@task.Title</h6>
                                    <p class="mb-1 text-muted small">@task.Assignee</p>
                                    <span class="badge @PriorityClass(task.Priority) me-1">@task.Priority</span>
                                    <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                    <div class="mt-2 d-flex gap-1">
                                        @if (colIndex > 0)
                                        {
                                            <button class="btn btn-sm btn-outline-secondary" disabled="@_moving" @onclick="() => MoveTaskAsync(task, _columns[colIndex - 1])">← Move Left</button>
                                        }
                                        @if (colIndex < _columns.Length - 1)
                                        {
                                            <button class="btn btn-sm btn-outline-secondary" disabled="@_moving" @onclick="() => MoveTaskAsync(task, _columns[colIndex + 1])">Move Right →</button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (_addingToColumn == column)
                        {
                            <div class="card border-primary">
                                <div class="card-body p-2">
                                    <input type="text" class="form-control form-control-sm mb-1" placeholder="Title" @bind="_newTitle" />
                                    <input type="text" class="form-control form-control-sm mb-1" placeholder="Assignee" @bind="_newAssignee" />
                                    <select class="form-select form-select-sm mb-1" @bind="_newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm mb-2" @bind="_newDueDate" />
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-sm btn-primary" disabled="@_saving" @onclick="SaveNewTaskAsync">Save</button>
                                        <button class="btn btn-sm btn-outline-secondary" @onclick="CancelAdd">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                    <div class="card-footer">
                        <button class="btn btn-sm btn-outline-primary w-100" @onclick="() => StartAdd(column)">+ Add Task</button>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private readonly string[] _columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> _allTasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchText = string.Empty;
    private bool _moving;

    // Add-task form state
    private string? _addingToColumn;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);
    private bool _saving;

    private int OverdueCount => _allTasks.Count(t => t.DueDate < DateTime.Today && t.Status != "Done");

    protected override async Task OnInitializedAsync() => await LoadTasksAsync();

    private async Task LoadTasksAsync()
    {
        _loading = true;
        _error = null;
        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status) =>
        _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status) =>
        _allTasks
            .Where(t => t.Status == status &&
                        (string.IsNullOrWhiteSpace(_searchText) ||
                         t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)))
            .ToList();

    private static string PriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTaskAsync(TaskItem task, string newStatus)
    {
        _moving = true;
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = _allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
                _allTasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _moving = false;
        }
    }

    private void StartAdd(string column)
    {
        _addingToColumn = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd() => _addingToColumn = null;

    private async Task SaveNewTaskAsync()
    {
        if (string.IsNullOrWhiteSpace(_newTitle) || _addingToColumn is null)
            return;

        _saving = true;
        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
            // CreateTaskAsync creates with default status; update if the target column differs
            if (created.Status != _addingToColumn)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, _addingToColumn);
                created = created with { Status = _addingToColumn };
            }
            _allTasks.Add(created);
            _addingToColumn = null;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
}

